import 'dart:io';

import 'package:archive/archive.dart';
import 'package:crypto/crypto.dart';
import 'package:path/path.dart' as p;

/// A different icon gets a different Shell cache key; ordinary app updates
/// reuse the same file. These names are generated by the Windows CMake bundle.
abstract final class WindowsIcon {
  static final _name = RegExp(r'^gooesteamkit-icon-([a-f0-9]{64})\.ico$');

  static bool _matches(String name, List<int> bytes) {
    final match = _name.firstMatch(name);
    return match != null &&
        match.end == name.length &&
        bytes.length >= 22 &&
        bytes[0] == 0 &&
        bytes[1] == 0 &&
        bytes[2] == 1 &&
        bytes[3] == 0 &&
        sha256.convert(bytes).toString() == match.group(1);
  }

  /// Validate before extracting any payload files, rather than choosing an
  /// arbitrary stale icon left in a reused build directory.
  static String payloadPath(Iterable<ArchiveFile> files) {
    final icons = files.where(
      (file) => file.isFile && _name.stringMatch(file.name) == file.name,
    );
    if (icons.length != 1) {
      throw StateError('The Windows payload must contain one branded icon');
    }
    final icon = icons.single;
    if (!_matches(icon.name, icon.content as List<int>)) {
      throw StateError('The Windows payload icon does not match its SHA256');
    }
    return icon.name;
  }

  /// Keep previously installed icon variants tracked until uninstall. User
  /// copies or pinned links may still refer to them. Only root-level files
  /// from our previous manifest with matching content are eligible.
  static Future<List<String>> retainedPaths(
    String directory,
    Iterable<String> previousManifest,
  ) async {
    final retained = <String>{};
    for (final entry in previousManifest) {
      final name = entry.trim();
      if (!_name.hasMatch(name)) continue;
      final path = p.join(directory, name);
      if (await FileSystemEntity.type(path, followLinks: false) !=
          FileSystemEntityType.file) {
        continue;
      }
      if (_matches(name, await File(path).readAsBytes())) retained.add(name);
    }
    return retained.toList();
  }
}
